def gen(rng):
    def fmt(n, edges):
        edges = list(edges)
        rng.shuffle(edges)
        return f"{n} {len(edges)}\n" + "\n".join(f"{u} {v}" for u, v in edges)

    def relabel(n, edges):
        p = list(range(n))
        rng.shuffle(p)
        return [(p[u], p[v]) for u, v in edges]

    def layered(L, w, pcyc, pself, p2):
        n = L * w
        edges = set()
        for l in range(L):
            base = l * w
            if l + 1 < L:
                nb = (l + 1) * w
                for j in range(w):
                    if rng.random() < p2:
                        for t in rng.sample(range(w), 2):
                            edges.add((base + j, nb + t))
                    else:
                        edges.add((base + j, nb + rng.randrange(w)))
            for j in range(0, w - 1, 2):
                if rng.random() < pcyc:
                    edges.add((base + j, base + j + 1))
                    edges.add((base + j + 1, base + j))
            for j in range(w):
                if rng.random() < pself:
                    edges.add((base + j, base + j))
        edges = sorted(edges)
        if len(edges) > 100000:
            edges = rng.sample(edges, 100000)
        return fmt(n, relabel(n, edges))

    tests = [
        fmt(1, []),
        fmt(1, [(0, 0)]),
        fmt(2, [(0, 1), (1, 0)]),
        fmt(2, [(0, 1)]),
        fmt(3, [(0, 1), (1, 2), (2, 0)]),
        fmt(4, [(0, 1), (0, 2), (2, 3)]),
        fmt(5, []),
    ]
    for _ in range(45):
        n = rng.randint(1, 10)
        allp = [(u, v) for u in range(n) for v in range(n)]
        m = rng.randint(0, min(len(allp), rng.choice([n, 2 * n])))
        tests.append(fmt(n, rng.sample(allp, m)))
    for _ in range(6):
        n = rng.randint(30, 40)
        allp = [(u, v) for u in range(n) for v in range(n)]
        tests.append(fmt(n, rng.sample(allp, rng.randint(n // 2, n))))
    # chains of 5000 nodes
    n = 5000
    chain = [(i, i + 1) for i in range(n - 1)]
    tests.append(fmt(n, relabel(n, chain)))
    tests.append(fmt(n, relabel(n, chain + [(n - 1, n - 1)])))
    tests.append(fmt(n, relabel(n, chain + [(n - 1, n - 2)])))
    # random sparse graphs with n <= 5000
    for n, m in ((3000, 3500), (5000, 5000), (2000, 6000)):
        allp = set()
        while len(allp) < m:
            allp.add((rng.randrange(n), rng.randrange(n)))
        tests.append(fmt(n, sorted(allp)))
    # large layered graphs: depth stays <= 5000, n up to 5*10^4, m up to 10^5
    tests.append(layered(2500, 20, 0.002, 0.0002, 0.97))
    tests.append(layered(2500, 20, 0.05, 0.001, 0.97))
    tests.append(layered(500, 100, 0.01, 0.0, 0.9))
    tests.append(layered(2500, 20, 0.0, 0.0, 0.97))
    tests.append(layered(2500, 20, 0.004, 0.0, 0.5))
    return tests
